$pdo=Database::getConnection();$manager=new ItAssetManager($pdo);$filters=['q'=>(string)($_GET['q']??''),'category'=>(string)($_GET['category']??''),'status'=>(string)($_GET['status']??'')];$rows=$manager->assets($filters);$stats=$manager->stats();$format=strtolower((string)($_GET['format']??'pdf'));$uid=(int)($_SESSION['user_id']??0);$author=trim((string)(($_SESSION['prenom']??'').' '.($_SESSION['nom']??'')))?:'Utilisateur';$documentId='SI-PARC-'.date('Ymd-His').'-U'.$uid;$documentCode='SI-PARC-REG-01';$brand=CompanyBranding::get($pdo);$company=(string)($brand['company_name']??'BANAMUR INDUSTRIES');
$performance=static fn($key)=>['performant'=>'Performant','standard'=>'Standard','replace'=>'À remplacer'][$key]??$key;$filterLabel=implode(' · ',array_filter([$filters['q']!==''?'Recherche : '.$filters['q']:'',$filters['category']!==''?'Type : '.(ItAssetManager::categories()[$filters['category']]??$filters['category']):'',$filters['status']!==''?'État : '.(ItAssetManager::conditions()[$filters['status']]??$filters['status']):'']))?:'Tous les équipements';

if(in_array($format,['excel','xlsx'],true)){
    $book=new Spreadsheet();$sheet=$book->getActiveSheet();$sheet->setTitle('Registre du parc');$book->getProperties()->setCreator($author)->setCompany($company)->setTitle('Registre du parc informatique')->setSubject('Document maîtrisé ISO 9001')->setDescription($documentId.' · '.$documentCode);
    $sheet->mergeCells('A1:R1')->setCellValue('A1',mb_strtoupper($company).' · REGISTRE DU PARC INFORMATIQUE');$sheet->mergeCells('A2:J2')->setCellValue('A2','DOCUMENT MAÎTRISÉ · FINÉA · ISO 9001');$sheet->mergeCells('K2:N2')->setCellValue('K2','Code qualité : '.$documentCode);$sheet->mergeCells('O2:R2')->setCellValue('O2','Édité le '.date('d/m/Y à H:i'));
    $sheet->mergeCells('A3:F3')->setCellValue('A3','Référence : '.$documentId);$sheet->mergeCells('G3:L3')->setCellValue('G3','Périmètre : '.$filterLabel);$sheet->mergeCells('M3:R3')->setCellValue('M3',count($rows).' équipement(s) exporté(s)');
    $headers=['Code actif','Type','Marque','Modèle','N° série','Utilisateur','Service','Site','CPU','RAM (Go)','Stockage','GPU','Système','IP','MAC','Mise en service','État','Performance'];$sheet->fromArray($headers,null,'A5');$line=6;
    foreach($rows as $row){$sheet->fromArray([$row['asset_code'],ItAssetManager::categories()[$row['category']]??$row['category'],$row['brand'],$row['model'],$row['serial_number'],$row['assigned_to'],$row['department'],$row['location'],$row['cpu'],$row['ram_gb'],$row['storage'].' '.$row['storage_type'],$row['gpu'],$row['operating_system'],$row['ip_address'],$row['mac_address'],$row['commissioned_at'],ItAssetManager::conditions()[$row['condition_status']]??$row['condition_status'],$performance($row['performance_level'])],null,'A'.$line++);}
    $last=max(6,$line-1);$sheet->getStyle('A1:R1')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB('0F172A');$sheet->getStyle('A1')->getFont()->setBold(true)->setSize(16)->getColor()->setRGB('FFFFFF');$sheet->getStyle('A2:R2')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB('E0E7FF');$sheet->getStyle('A2:R2')->getFont()->setBold(true)->getColor()->setRGB('312E81');$sheet->getStyle('A3:R3')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB('F8FAFC');$sheet->getStyle('A5:R5')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setRGB('FABD02');$sheet->getStyle('A5:R5')->getFont()->setBold(true)->getColor()->setRGB('000000');$sheet->getStyle('A5:R'.$last)->getBorders()->getAllBorders()->setBorderStyle(Border::BORDER_THIN)->getColor()->setRGB('CBD5E1');$sheet->getStyle('A1:R'.$last)->getAlignment()->setVertical(Alignment::VERTICAL_CENTER)->setWrapText(true);$sheet->freezePane('A6');$sheet->setAutoFilter('A5:R'.$last);foreach(range('A','R') as $column)$sheet->getColumnDimension($column)->setAutoSize(true);$sheet->getPageSetup()->setOrientation('landscape')->setFitToWidth(1)->setFitToHeight(0);$sheet->getPageMargins()->setTop(.5)->setRight(.25)->setLeft(.25)->setBottom(.5);
    while(ob_get_level()>0)ob_end_clean();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="registre_parc_informatique_'.$documentId.'.xlsx"');header('Cache-Control: max-age=0');(new Xlsx($book))->save('php://output');exit;
}

class ItAssetRegisterPdf extends TCPDF {use CompanyPdfTemplate;public function Header():void{$this->drawCompanyPdfHeader();}public function Footer():void{$this->drawCompanyPdfFooter();}}
$pdf=new ItAssetRegisterPdf('L','mm','A4',true,'UTF-8',false);$pdf->companyPdfTitle='Registre du parc informatique';$pdf->companyPdfType='État détaillé des actifs informatiques';$pdf->companyPdfId=$documentId;$pdf->companyPdfCode=$documentCode;$pdf->companyPdfQrPayload=json_encode(['document'=>$documentId,'type'=>'registre_parc_informatique','count'=>count($rows),'filters'=>$filters,'generated_at'=>date(DATE_ATOM)],JSON_UNESCAPED_UNICODE);$pdf->SetCreator('Finéa');$pdf->SetAuthor($author);$pdf->SetTitle('Registre du parc informatique');$pdf->SetMargins(14,38,14);$pdf->SetAutoPageBreak(true,25);$pdf->AddPage();
