$pdf->SetY(64);$pdf->SetFillColor(238,242,255);$pdf->SetDrawColor(199,210,254);$pdf->SetTextColor(49,46,129);$pdf->SetFont('dejavusans','',7);$pdf->MultiCell(269,8,'Périmètre exporté : '.$filterLabel,1,'L',true,1,'','',true,0,false,true,8,'M');$pdf->Ln(3);
$cols=[['CODE',26,'L'],['MATÉRIEL',39,'L'],['AFFECTATION',43,'L'],['CONFIGURATION',62,'L'],['LOCALISATION',36,'L'],['ÉTAT',31,'L'],['PERFORMANCE',32,'L']];$header=static function(TCPDF $pdf)use($cols):void{$pdf->SetFillColor(23,37,84);$pdf->SetTextColor(255);$pdf->SetFont('dejavusans','B',6.5);foreach($cols as [$label,$w,$align])$pdf->MultiCell($w,9,$label,1,$align,true,0,'','',true,0,false,true,9,'M');$pdf->Ln();};$header($pdf);
foreach($rows as $index=>$row){$cells=[$row['asset_code'],trim($row['brand'].' '.$row['model'])."\nN/S ".($row['serial_number']?:'—'),($row['assigned_to']?:'Non affecté')."\n".$row['department'],($row['cpu']?:'CPU non renseigné')."\n".($row['ram_gb']?(float)$row['ram_gb'].' Go RAM · ':'').trim($row['storage'].' '.$row['storage_type'])."\n".$row['operating_system'],($row['location']?:'—')."\n".($row['commissioned_at']?date('d/m/Y',strtotime($row['commissioned_at'])):'Date inconnue'),ItAssetManager::conditions()[$row['condition_status']]??$row['condition_status'],$performance($row['performance_level'])];$pdf->SetFont('dejavusans','',6.3);$heights=[];foreach($cells as $i=>$cell)$heights[]=$pdf->getStringHeight($cols[$i][1]-3,(string)$cell);$height=max(10,min(20,max($heights)+3));if($pdf->GetY()+$height>184){$pdf->AddPage();$pdf->SetY(40);$header($pdf);}$pdf->SetFillColor(248,250,252);$pdf->SetDrawColor(226,232,240);foreach($cells as $i=>$cell){$pdf->SetTextColor(51,65,85);$pdf->SetFont('dejavusans',$i===0?'B':'',6.3);$pdf->MultiCell($cols[$i][1],$height,(string)$cell,1,$cols[$i][2],$index%2===1,0,'','',true,0,false,true,$height,'M');}$pdf->Ln();}
if(!$rows){$pdf->SetFont('dejavusans','I',9);$pdf->SetTextColor(100,116,139);$pdf->MultiCell(269,22,'Aucun équipement ne correspond aux filtres transmis.',1,'C',true,1,'','',true,0,false,true,22,'M');}$pdf->Output('registre_parc_informatique_'.$documentId.'.pdf','I');exit;
